-- 000011_customer_billing_rules (T187)
-- Per-customer billing rules for commercial customers:
--   po_required            invoices can't be sent without a PO number
--   default_po_number      copied onto new invoices that have none
--   billing_approver_*     the customer's named approver for extra work
--   nte_limit              not-to-exceed: extra work (jobs not generated by an
--                          agreement) estimated above it can't be scheduled
--                          until the approver's OK is recorded (job_approvals)
--   consolidated_billing   one monthly invoice per customer (used by T188)

ALTER TABLE customers ADD COLUMN IF NOT EXISTS po_required BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE customers ADD COLUMN IF NOT EXISTS default_po_number VARCHAR(100);
ALTER TABLE customers ADD COLUMN IF NOT EXISTS billing_approver_name VARCHAR(100);
ALTER TABLE customers ADD COLUMN IF NOT EXISTS billing_approver_email VARCHAR(255);
ALTER TABLE customers ADD COLUMN IF NOT EXISTS nte_limit NUMERIC(12,2);
ALTER TABLE customers ADD COLUMN IF NOT EXISTS consolidated_billing BOOLEAN NOT NULL DEFAULT FALSE;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'customers_nte_limit_nonnegative') THEN
        ALTER TABLE customers ADD CONSTRAINT customers_nte_limit_nonnegative CHECK (nte_limit IS NULL OR nte_limit >= 0);
    END IF;
END
$$;

-- The approver's OK for one job, recorded by office staff (V1: no
-- customer-facing approval flow yet). Tenant-owned, with the RLS policy of
-- migration 000007.
CREATE TABLE IF NOT EXISTS job_approvals (
    id             UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id      UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    job_id         UUID NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
    approver_name  VARCHAR(100),
    approver_email VARCHAR(255) NOT NULL,
    amount         NUMERIC(12,2) NOT NULL CHECK (amount >= 0),
    approved_at    TIMESTAMPTZ NOT NULL,
    notes          TEXT,
    recorded_by    UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_job_approvals_tenant_job ON job_approvals (tenant_id, job_id);

ALTER TABLE job_approvals ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON job_approvals;
CREATE POLICY tenant_isolation ON job_approvals
    USING (app_rls_bypass() OR tenant_id = app_current_tenant())
    WITH CHECK (app_rls_bypass() OR tenant_id = app_current_tenant());
